import {createRequire} from 'node:module';
import fs from 'node:fs';
const rq=createRequire(process.cwd()+'/package.json');
const provider=rq.resolve('@vitest/browser-playwright');
const pr=createRequire(provider);
const playwright=pr.resolve('playwright');
const pjson=pr.resolve('playwright/package.json');
const core=createRequire(pjson).resolve('playwright-core/package.json');
console.log(JSON.stringify({provider,playwright,pjson,playwrightVersion:JSON.parse(fs.readFileSync(pjson)).version,core,coreVersion:JSON.parse(fs.readFileSync(core)).version},null,2));
